convergences = [
 {"date":"1685-10-18","label":"Chaumont's audience with King Narai at Ayutthaya","eyes":["chaumont","choisy"],"note":"The ambassador's relation dwells on protocol and the conversion plea; Choisy, behind him, notices what Narai actually wanted. Fifteen months later the same choreography of letters and bows would be staged at Versailles with the roles reversed."},
 {"date":"1685-12-11","label":"Last days at Lopburi: eclipse, appointments, farewell","eyes":["tachard","forbin","chaumont","choisy"],"note":"On 10–12 December the Jesuits watched an eclipse with the king, Forbin was made governor of Bangkok against his will, missionary privileges were signed and Chaumont took leave. Each saw a different Siam: a patron of science, a trap, a mission field, a diplomatic success."},
 {"date":"1685-12-22","label":"The embassy sails west with Kosa Pan aboard","eyes":["kosa-pan","tachard","choisy"],"note":"French and Siamese envoys share one ship for six months; the French journals survive, the Siamese record of the voyage does not."},
 {"date":"1686-06-18","label":"Landing at Brest, while another Siamese embassy is lost in Africa","eyes":["choisy","kosa-pan","chamnan"],"note":"As Choisy's journal closes and Kosa Pan's scribes begin counting trees at Brest, Ok-khun Chamnan's party, wrecked in April, has only lately staggered into the Dutch Cape colony after a month on foot: two Siamese embassies to Europe, one feted, one half-starved."},
 {"date":"1686-09-01","label":"The audience at Versailles","eyes":["dangeau","sainctot","vise","forbin"],"note":"Three French records of one ceremony: Dangeau notes the throne and the backward retreat, Sainctot the calibrated rank, the Mercure the crowd and the compliments. Kosa Pan's own record is lost. In the same weeks Forbin, in Bangkok, was fighting the Makassar revolt, a Siam no one at Versailles was describing."},
 {"date":"1687-03-01","label":"The return voyage, with troops","eyes":["la-loubere","kosa-pan","tachard","ceberet"],"note":"The returning ambassadors share the fleet with the soldiers meant for Bangkok and Mergui. La Loubère's report and Kosa Pan's thank-you letters from the Cape speak of friendship; the cargo spoke of garrisons."},
 {"date":"1687-11-02","label":"La Loubère's reception in Siam","eyes":["la-loubere","chamnan","ceberet","kosa-pan"],"note":"Now the French are watched: Chamnan receives them, the returned envoys talk of France, and La Loubère studies Siamese manners as closely as the Mercure had studied Siamese bows."},
 {"date":"1688-01-03","label":"Departures from Siam","eyes":["la-loubere","chamnan","tachard"],"note":"A French embassy leaves on bad terms with Phaulkon, carrying a Siamese one that will reach Rome only after its king is dead."},
 {"date":"1688-06-06","label":"The revolution and the siege of Bangkok","eyes":["kosa-pan","mergui-officer","chronicle"],"note":"The former ambassador to Versailles escorts the French general to be dispossessed; at Mergui a French officer is chained by his own soldiers; the chronicle later records only a change of king."},
]

